/* interlink.js — Related-reading block + gwern-style hover link previews.
 *
 * Data source: two committed JSON files copied into _site/ by Quarto
 * (registered under `resources:` in _quarto.yml), generated by
 * scripts/build_indexes.py. No build-time runtime beyond Quarto is needed.
 *
 *   related-index.json : { "<slug>": [ {title, url, date, categories} ] }
 *   link-index.json    : { "/writing/<slug>.html": {title, blurb, date} }
 *
 * FEATURE A — Related reading (must-have): on essay pages, inject a
 *   "Related reading" block before the footer from related-index.json.
 * FEATURE B — Hover previews (best-effort): on any <a> whose href resolves
 *   to a link-index key, show a floating brand-styled card on hover/focus.
 *
 * Defensive throughout: a missing/empty index, or a slug with no entry,
 * results in no block and no errors.
 */
(function () {
  "use strict";

  // ---- Resolve site-root-relative URLs (works locally and in prod) --------
  // JSON files live at the origin root; build the URL from the origin so it
  // resolves correctly regardless of how deep the current page is.
  function originRoot(path) {
    return window.location.origin + "/" + path.replace(/^\/+/, "");
  }

  // ---- Essay-page detection ----------------------------------------------
  // An essay lives at /writing/<slug>(.html). Exclude the writing index.
  function essaySlug() {
    var p = window.location.pathname;
    var m = p.match(/\/writing\/([^/]+?)(?:\.html)?\/?$/);
    if (!m) return null;
    var slug = m[1];
    if (!slug || slug === "index") return null;
    return slug;
  }

  // ---- Normalize an href to a link-index key (/writing/<slug>.html) -------
  // Handles absolute, relative, .html and cleanUrls (no extension) forms.
  function hrefToKey(anchor) {
    var href = anchor.getAttribute("href");
    if (!href) return null;
    // Ignore pure fragments / non-http schemes.
    if (href.charAt(0) === "#") return null;
    if (/^(mailto:|tel:|javascript:)/i.test(href)) return null;
    var url;
    try {
      url = new URL(anchor.href); // resolved absolute form
    } catch (e) {
      return null;
    }
    // Same-origin only.
    if (url.origin !== window.location.origin) return null;
    var path = url.pathname;
    var m = path.match(/\/writing\/([^/]+?)(?:\.html)?\/?$/);
    if (!m) return null;
    var slug = m[1];
    if (!slug || slug === "index") return null;
    return "/writing/" + slug + ".html";
  }

  // ---- Fetch a JSON resource, resolve to {} on any failure ----------------
  function fetchJSON(path) {
    return fetch(originRoot(path), { credentials: "same-origin" })
      .then(function (r) { return r.ok ? r.json() : {}; })
      .catch(function () { return {}; });
  }

  function escapeHTML(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  // Format an ISO date (YYYY-MM-DD) as "April 28, 2026". Falls back to raw.
  var MONTHS = ["January","February","March","April","May","June","July",
                "August","September","October","November","December"];
  function fmtDate(iso) {
    if (!iso) return "";
    var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(iso);
    if (!m) return iso;
    var mo = parseInt(m[2], 10) - 1;
    if (mo < 0 || mo > 11) return iso;
    return MONTHS[mo] + " " + parseInt(m[3], 10) + ", " + m[1];
  }

  // =========================================================================
  // FEATURE A — Related reading block
  // =========================================================================
  function buildRelated(relatedIndex) {
    var slug = essaySlug();
    if (!slug) return;
    var items = relatedIndex && relatedIndex[slug];
    if (!Array.isArray(items) || items.length === 0) return; // hide entirely

    // Insertion point: end of the article column so it lands inside the
    // reading measure, just before the footer. Prefer #quarto-document-content
    // (the <main>); fall back to <main> then <footer>'s parent.
    var main = document.getElementById("quarto-document-content") ||
               document.querySelector("main.content") ||
               document.querySelector("main");
    if (!main) return;

    var section = document.createElement("aside");
    section.className = "related-reading";
    section.setAttribute("aria-label", "Related reading");

    var kicker = document.createElement("span");
    kicker.className = "related-reading__kicker";
    kicker.textContent = "Related reading";
    section.appendChild(kicker);

    var ul = document.createElement("ul");
    ul.className = "related-reading__list";

    items.slice(0, 3).forEach(function (it) {
      var li = document.createElement("li");
      li.className = "related-reading__item";

      var a = document.createElement("a");
      a.className = "related-reading__title";
      a.href = it.url;
      a.textContent = it.title || it.url;
      li.appendChild(a);

      if (it.date) {
        var d = document.createElement("span");
        d.className = "related-reading__date";
        d.textContent = fmtDate(it.date);
        li.appendChild(d);
      }
      ul.appendChild(li);
    });

    section.appendChild(ul);
    main.appendChild(section);
  }

  // =========================================================================
  // FEATURE B — Hover link previews
  // =========================================================================
  function initPreviews(linkIndex) {
    if (!linkIndex || typeof linkIndex !== "object") return;
    var keys = Object.keys(linkIndex);
    if (keys.length === 0) return;

    var card = null;
    var showTimer = null;
    var activeAnchor = null;

    function ensureCard() {
      if (card) return card;
      card = document.createElement("div");
      card.className = "interlink-preview";
      card.setAttribute("role", "tooltip");
      document.body.appendChild(card);
      return card;
    }

    function position(anchor) {
      var c = ensureCard();
      var r = anchor.getBoundingClientRect();
      // Measure card after content set.
      var cw = c.offsetWidth || 320;
      var ch = c.offsetHeight || 120;
      var margin = 8;
      var left = r.left;
      // Keep within viewport horizontally.
      if (left + cw + margin > window.innerWidth) {
        left = Math.max(margin, window.innerWidth - cw - margin);
      }
      if (left < margin) left = margin;
      // Prefer below the link; flip above if it would overflow the bottom.
      var top = r.bottom + 6;
      if (top + ch + margin > window.innerHeight && r.top - ch - 6 > margin) {
        top = r.top - ch - 6;
      }
      c.style.left = Math.round(left) + "px";
      c.style.top = Math.round(top) + "px";
    }

    function render(data) {
      var c = ensureCard();
      var kicker = data.date ? fmtDate(data.date) : "Essay";
      c.innerHTML =
        '<span class="interlink-preview__kicker">' + escapeHTML(kicker) + "</span>" +
        '<p class="interlink-preview__title">' + escapeHTML(data.title || "") + "</p>" +
        (data.blurb ? '<p class="interlink-preview__blurb">' + escapeHTML(data.blurb) + "</p>" : "");
    }

    function show(anchor, data) {
      activeAnchor = anchor;
      render(data);
      position(anchor);
      // Re-position after layout settles (card height now known).
      requestAnimationFrame(function () {
        if (activeAnchor === anchor) {
          position(anchor);
          ensureCard().classList.add("is-visible");
        }
      });
    }

    function hide() {
      if (showTimer) { clearTimeout(showTimer); showTimer = null; }
      activeAnchor = null;
      if (card) card.classList.remove("is-visible");
    }

    function arm(anchor, data) {
      if (showTimer) clearTimeout(showTimer);
      showTimer = setTimeout(function () { show(anchor, data); }, 120);
    }

    // Event delegation so dynamically-injected links (Related block) work too.
    function dataFor(target) {
      if (!target || target.nodeType !== 1) return null;
      var a = target.closest ? target.closest("a") : null;
      if (!a) return null;
      var key = hrefToKey(a);
      if (!key) return null;
      var d = linkIndex[key];
      return d ? { anchor: a, data: d } : null;
    }

    document.addEventListener("mouseover", function (e) {
      var hit = dataFor(e.target);
      if (!hit) return;
      // Don't re-arm if already showing for this anchor.
      if (activeAnchor === hit.anchor) return;
      arm(hit.anchor, hit.data);
    });

    document.addEventListener("mouseout", function (e) {
      var hit = dataFor(e.target);
      if (!hit) return;
      // Only hide if leaving the active anchor entirely.
      var to = e.relatedTarget;
      if (to && hit.anchor.contains(to)) return;
      hide();
    });

    // Keyboard accessibility: focus shows, blur hides.
    document.addEventListener("focusin", function (e) {
      var hit = dataFor(e.target);
      if (!hit) return;
      arm(hit.anchor, hit.data);
    });
    document.addEventListener("focusout", function (e) {
      var hit = dataFor(e.target);
      if (!hit) return;
      hide();
    });

    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape") hide();
    });
    // Hide on scroll so a stale card doesn't float in the wrong place.
    window.addEventListener("scroll", hide, { passive: true });
  }

  // ---- Boot ---------------------------------------------------------------
  function boot() {
    var onEssay = !!essaySlug();
    // Related reading only matters on essay pages.
    if (onEssay) {
      fetchJSON("related-index.json").then(buildRelated);
    }
    // Hover previews apply to any page that links to essays, but per spec we
    // scope the whole feature set to essay pages to avoid touching listing
    // pages (home / writing index / about). Essay pages still link to other
    // essays (e.g. the Related block), so previews are useful there.
    if (onEssay) {
      fetchJSON("link-index.json").then(initPreviews);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
})();
